'use strict';
(() => {
 const $ = id => document.getElementById(id);
 const clone = x => JSON.parse(JSON.stringify(x));
 const finite = x => typeof x === 'number' && Number.isFinite(x);
 const num = id => Number($(id).value);
 const money = x => finite(x) ? new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Math.abs(x)<.5?0:x) : '—';
 const signed = x => finite(x) ? (x>.5?'+':'')+money(x) : '—';
 const pct = x => finite(x) ? (x*100).toFixed(2)+'%' : '—';
 const rate = x => finite(x) ? x.toLocaleString('en-US',{maximumFractionDigits:3})+'%' : '—';
 const decimal = x => finite(x) ? x.toLocaleString('en-US',{maximumFractionDigits:3}) : '—';
 const labels = {A:"A · Index ETF",B:"B · Long-only + TLH",C:"C · 130/30, no harvesting",D:"D · Tax-aware QP + TLH"};
 const colors = {A:'#667b83',B:'#4779ab',C:'#bc8a4b',D:'#008579'};
 const controls = {cash:'initial_cash',start:'start_date',end:'end_date',benchmark:'benchmark',finance:'financing_pct',borrow:'borrow_pct',manager:'manager_pct',advisor:'advisor_pct','tax-st':'tax_st_pct','tax-lt':'tax_lt_pct',trade:'transaction_pct',rebate:'rebate_pct',rebalance:'rebalance_every_sessions',threshold:'harvest_threshold_pct',maintenance:'maintenance_equity_to_gross_pct'};
 let defaults,lastResult,busy=false,dirty=false,timer,seconds=0,metric='delta_D_A',selectedCost,activeGroup='demo',drafts={};
 function el(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=String(text);return n;}
 function add(parent,tag,className,text){const n=el(tag,className,text);parent.appendChild(n);return n;}
 function section(parent,title,description,chartNumber){const panel=add(parent,'section','panel report-section');const head=add(panel,'div','section-head');const left=add(head,'div');if(chartNumber)add(left,'span','chart-number',chartNumber);add(left,'h3','',title);if(description)add(left,'p','section-description',description);return {panel,head};}
 function details(parent,title,open=false){const d=add(parent,'details','details');d.open=open;add(d,'summary','',title);return d;}
 function table(parent,columns,rows){const wrap=add(parent,'div','table-scroll');const t=add(wrap,'table');const tr=add(add(t,'thead'),'tr');columns.forEach(([name])=>add(tr,'th','',name));const body=add(t,'tbody');for(const r of rows){const row=add(body,'tr',r.strategy==='D'?'emphasis':'');for(const[,key,format]of columns){const v=typeof key==='function'?key(r):r[key];add(row,'td','',format?format(v):v===undefined||v===null?'—':String(v));}}return t;}
 function sourceGroup(){return $('data-source').value==='demo'?'demo':'observed';}
 function baseConfig(){return defaults[sourceGroup()==='demo'?'demo_config':'observed_config'];}
 function positionsText(c){return(c.positions||[]).map(p=>[p.ticker,p.side,p.weight,c.substitutes?.[p.ticker]?.ticker||''].join(',')).join('\n');}
 function draft(){return{start:$('start').value,end:$('end').value,benchmark:$('benchmark').value,positions:$('positions').value,year:$('gain-year').value};}
 function applyGroup(c,d){$('start').value=d?.start||c.start_date;$('end').value=d?.end||c.end_date;$('benchmark').value=d?.benchmark||c.benchmark||'SPY';$('positions').value=d?.positions||positionsText(c);$('gain-year').value=d?.year||(c.outside_gain_events||[])[0]?.year||c.event_year||Number(c.start_date.slice(0,4));}
 function sourceNote(){const source=$('data-source').value;$('upload-row').hidden=source!=='uploaded';$('source-note').textContent={demo:"Synthetic prices for interface and model checks only. These are not market evidence, manager performance or forecasts.",live:"Download historical prices, dividends and splits, including a pre-start estimation window. Missing data stops the run; prices are never invented.",uploaded:"Upload raw price-history JSON with pre-start observations and source metadata. Uploading a file does not independently verify its contents.",local_cache:"Use the frozen local snapshot. Allow enough pre-start history for risk estimation. Choose another source if the snapshot is unavailable."}[source];}
 function rates(value,label){const a=value.split(/[,，]/).map(x=>x.trim());if(!a.length||a.length>3||a.some(x=>x===''))throw Error(label+" requires 1–3 numbers separated by commas.");const out=a.map(Number);if(out.some(x=>!Number.isFinite(x)||x<0||x>30))throw Error(label+" must be between 0% and 30%.");if(new Set(out).size!==out.length)throw Error(label+" must not contain duplicates.");return out.sort((a,b)=>a-b);}
 function optionalFields(){const sens=$('sensitivity-enabled').checked,mc=$('mc-enabled').checked;$('sensitivity-fields').hidden=!sens;$('mc-fields').hidden=!mc;for(const id of ['finance-rates','borrow-rates'])$(id).disabled=busy||!sens;for(const id of ['paths','seed'])$(id).disabled=busy||!mc;try{const n=rates($('finance-rates').value,"Financing test points").length,m=rates($('borrow-rates').value,"Borrow test points").length;$('grid-note').textContent=n+' × '+m+' = '+n*m+" paired cost scenarios. Each cell reruns all four strategies and the QP, increasing calculation time.";}catch(_){$('grid-note').textContent="Use up to three distinct test points per axis, for at most nine cells.";}}
 function markDirty(){if(busy)return;optionalFields();if(lastResult){dirty=true;$('stale').hidden=false;$('output').classList.add('old-result');$('export').disabled=true;$('print').disabled=true;}$('status').textContent="Inputs changed. Run the study again to update all four strategies and results.";}
 function reset(){if(!defaults||busy)return;$('data-source').value='demo';activeGroup='demo';drafts={};const c=defaults.demo_config;for(const[id,key]of Object.entries(controls))if(c[key]!==undefined)$(id).value=c[key];applyGroup(c);const gain=(c.outside_gain_events||[])[0];$('gain').value=gain?.amount||0;$('gain-character').value=gain?.character||'st';const options=defaults.defaults||{};const o=options.optimization||defaults.optimization||{};for(const[id,key,fallback]of [['risk-aversion','risk_aversion',50],['lookback','lookback',126],['long-cap','long_cap_pct',60],['short-cap','short_cap_pct',20]])$(id).value=o[key]??fallback;const s=options.sensitivities||defaults.sensitivities||{};$('sensitivity-enabled').checked=s.enabled!==false;$('finance-rates').value=(s.financing_rates||[3,5,7]).join(', ');$('borrow-rates').value=(s.borrow_rates||[0,1,3]).join(', ');$('mc-enabled').checked=false;$('paths').value=5;$('seed').value=4511;$('replacement-reviewed').checked=true;$('form-error').hidden=true;sourceNote();optionalFields();markDirty();if(!lastResult)$('status').textContent="Example ready. For a quick first run, turn off the additional analyses, then add a cost grid or simulated paths.";}
 function readPositions(){const rows=$('positions').value.trim().split(/\n/).filter(x=>x.trim());if(rows.length<2||rows.length>20)throw Error("Enter 2–20 original securities, including both long and short positions.");const ps=[],subs={},names=[];for(const[line,index]of rows.map((line,i)=>[line,i])){const p=line.split(',').map(x=>x.trim());if(p.length!==4)throw Error("Row "+(index+1)+" requires four columns: ticker,side,weight,replacement.");const ticker=p[0].toUpperCase(),side=p[1].toLowerCase(),replacement=p[3].toUpperCase(),weight=Number(p[2]);if(!/^[A-Z][A-Z0-9-]{0,14}$/.test(ticker)||!/^[A-Z][A-Z0-9-]{0,14}$/.test(replacement)||!['long','short'].includes(side)||!Number.isFinite(weight)||weight<=0)throw Error("Row "+(index+1)+" has an invalid ticker, side or weight.");ps.push({ticker,side,weight});subs[ticker]={ticker:replacement,reviewed_not_substantially_identical:true,review_basis:'Explicit research assumption; not legal approval.'};names.push(ticker,replacement);}if(new Set(names).size!==names.length)throw Error("This batch engine requires every original and replacement ticker to be unique.");const nl=ps.filter(p=>p.side==='long').length,ns=ps.length-nl;if(!nl||!ns)throw Error("The 130/30 candidate portfolio must include both long and short positions.");if(nl*num('long-cap')<130-1e-8||ns*num('short-cap')<30-1e-8)throw Error("The position caps and security counts cannot support 130/30. Add securities or raise the caps.");return{positions:ps,substitutes:subs};}
 async function payload(){const c=clone(baseConfig());for(const[id,key]of Object.entries(controls))c[key]=['start','end','benchmark'].includes(id)?$(id).value:num(id);c.benchmark=c.benchmark.trim().toUpperCase();if(c.end_date<=c.start_date)throw Error("The final date must be later than the start date.");Object.assign(c,readPositions(),{long_exposure_pct:130,short_exposure_pct:30,ordinary_tax_pct:num('tax-st'),dividend_tax_pct:num('tax-lt')});const amount=num('gain'),year=num('gain-year');if(amount>0&&(!Number.isInteger(year)||year<Number(c.start_date.slice(0,4))||year>Number(c.end_date.slice(0,4))))throw Error("A positive outside gain requires a whole calendar year within the study period.");c.outside_gain_events=amount>0?[{year,amount,character:$('gain-character').value}]:[];if(!$('replacement-reviewed').checked)throw Error("Confirm the listed replacement-security assumptions first.");const s=$('sensitivity-enabled').checked;const request={config:c,data_source:$('data-source').value,optimization:{risk_aversion:num('risk-aversion'),lookback:num('lookback'),long_cap_pct:num('long-cap'),short_cap_pct:num('short-cap')},sensitivities:{enabled:s,financing_rates:s?rates($('finance-rates').value,"Financing test points"):[c.financing_pct],borrow_rates:s?rates($('borrow-rates').value,"Borrow test points"):[c.borrow_pct]},monte_carlo:{enabled:$('mc-enabled').checked,paths:$('mc-enabled').checked?num('paths'):5,seed:$('mc-enabled').checked?num('seed'):4511}};if(request.data_source==='uploaded'){const f=$('history-file').files[0];if(!f)throw Error("Select a raw price-history JSON file.");if(f.size>4500000)throw Error("The price-history JSON must be smaller than 4.5 MB.");try{request.history=JSON.parse(await f.text());}catch(_){throw Error("Unable to read the price-history JSON.");}}return request;}
 function svg(parent,name,attrs,text){const n=document.createElementNS('http://www.w3.org/2000/svg',name);for(const[k,v]of Object.entries(attrs||{}))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=String(text);parent.appendChild(n);return n;}
 function compact(x){const a=Math.abs(x);return(a>=1e6?(x/1e6).toFixed(2)+'M':a>=1000?(x/1000).toFixed(0)+'k':x.toFixed(0));}
 function lineChart(parent,series,title,{zero=false}={}){series=series.filter(s=>s.points.some(p=>finite(p.value)));if(!series.length){add(parent,'p','warning',"No usable daily observations are available for this chart. Missing curves are not estimated.");return;}const points=series.flatMap(s=>s.points.filter(p=>finite(p.value))),times=points.map(p=>Date.parse(p.date)),values=points.map(p=>p.value);let min=Math.min(...values),max=Math.max(...values);if(zero){min=Math.min(0,min);max=Math.max(0,max);}const pad=Math.max((max-min)*.09,Math.max(Math.abs(max),1)*.03);min=(zero&&values.every(v=>v>=0))?0:min-pad;max+=pad;const lo=Math.min(...times),hi=Math.max(...times),left=82,right=870,top=22,bottom=232,x=v=>left+(Date.parse(v)-lo)/(hi-lo||1)*(right-left),y=v=>bottom-(v-min)/(max-min||1)*(bottom-top);const plot=svg(parent,'svg',{viewBox:'0 0 900 272',class:'chart',role:'img','aria-label':title});svg(plot,'title',{},title);for(let i=0;i<=4;i++){const v=min+(max-min)*i/4;svg(plot,'line',{x1:left,x2:right,y1:y(v),y2:y(v),class:'chart-grid'});svg(plot,'text',{x:left-11,y:y(v)+4,'text-anchor':'end'},'$'+compact(v));}if(min<=0&&max>=0)svg(plot,'line',{x1:left,x2:right,y1:y(0),y2:y(0),class:'zero-line'});for(const t of [lo,(lo+hi)/2,hi])svg(plot,'text',{x:left+(t-lo)/(hi-lo||1)*(right-left),y:255,'text-anchor':'middle'},new Date(t).toISOString().slice(0,7));for(const s of series){let path='',active=false;for(const p of s.points){if(!finite(p.value)){active=false;continue;}path+=(active?'L':'M')+x(p.date).toFixed(2)+' '+y(p.value).toFixed(2)+' ';active=true;}svg(plot,'path',{d:path,fill:'none',stroke:s.color||colors[s.key]||colors.D,'stroke-width':s.key==='D'?2.7:1.9});}const legend=add(parent,'div','legend');for(const s of series){const item=add(legend,'span');const swatch=add(item,'i');swatch.style.backgroundColor=s.color||colors[s.key]||colors.D;item.appendChild(document.createTextNode(s.name||labels[s.key]));}}
 function dailySeries(result,key,field){return{key,name:labels[key],points:(result.strategies?.[key]?.daily||[]).map(d=>({date:d.date,value:d[field]}))};}
 function differenceSeries(result,strategy,baseline,field,name){const base=new Map((result.strategies?.[baseline]?.daily||[]).map(d=>[d.date,d[field]]));return{key:strategy,name,points:(result.strategies?.[strategy]?.daily||[]).map(d=>({date:d.date,value:finite(base.get(d.date))&&finite(d[field])?base.get(d.date)-d[field]:null}))};}
 function comparisonRows(result){return(result.comparison||[]).map(r=>({...r,label:labels[r.strategy]||r.label}));}
 function renderTop(out,result){const kind=result.data_kind;const p=add(out,'div','provenance '+(kind==='observed'?'observed':kind==='synthetic'?'':'unverified'));add(p,'strong','',kind==='synthetic'?"Synthetic example · Not historical investment performance":kind==='observed'?"Observed prices · Hypothetical trades and client conditions":"User-provided data · Source not independently verified");add(p,'p','',result.data_label||"Check the exported price sources and assumptions.");if(kind==='synthetic')add(p,'p','',"Artificial paths support interface and model validation. They are not market evidence or return forecasts.");const c=result.request?.config||{},event=(c.outside_gain_events||[])[0],caseText="Initial "+money(c.initial_cash)+" | "+c.start_date+" to "+c.end_date+" | Outside gain "+(event?money(event.amount)+" ("+event.year+", "+event.character.toUpperCase()+")":"$0 (no event)")+" | Benchmark "+(c.benchmark||'SPY')+" | Full liquidation at the end";add(out,'p','case-line',caseText);add(out,'p','print-case','P107 Tax-Aware Research Lab\n'+caseText+"\nData: "+(result.data_label||kind)+"\nFinancing "+rate(c.financing_pct)+" / Borrow "+rate(c.borrow_pct)+" / Core management "+rate(c.manager_pct)+' / ST '+rate(c.tax_st_pct)+' / LT '+rate(c.tax_lt_pct)+"\nOptimization "+JSON.stringify(result.request?.optimization||{})+'\nRun '+result.run_id);const rows=comparisonRows(result),d=rows.find(r=>r.strategy==='D');const cards=add(out,'div','summary-cards');const best=rows.filter(r=>finite(r.terminal_wealth)).sort((a,b)=>b.terminal_wealth-a.terminal_wealth)[0];for(const[title,value,note,numeric]of [["D vs A: terminal wealth difference",d?.delta_vs_A,"Includes allocation, leverage, trading, costs and taxes.",true],["D vs C: terminal wealth difference",d?.delta_vs_C,"Same candidate directions, but weights and trades also change; this is not pure tax savings.",true],["Highest terminal wealth on this path",best?.strategy||'—',"Applies only to this path and these inputs. It does not establish general client suitability.",false]]){const card=add(cards,'article','panel summary-card');add(card,'p','card-label',title);add(card,'div','card-value '+(numeric&&finite(value)?value>=0?'positive':'negative':''),numeric?signed(value):best?labels[value]:value);add(card,'p','',note);}const {panel}=section(out,"Four-strategy terminal results","Wealth already reflects each strategy's modeled taxes and costs. Do not add tax differences again. B is a selected stock basket, not a complete commercial index-tracking product.");table(panel,[["Strategy",'label'],["Terminal after-tax wealth",'terminal_wealth',money],["vs A",'delta_vs_A',signed],["All modeled taxes",'total_taxes',money],["Financing and fees",'total_costs',money],["Rule-triggered harvested losses",'harvested_losses',money],["ST carryforward",'carry_st',money],["LT carryforward",'carry_lt',money]],rows);}
 function renderCharts(out,r){let s=section(out,"After-tax book wealth through full liquidation","Interim book wealth deducts taxes and costs already paid but may retain unpaid exit taxes. The last point reflects full liquidation and modeled tax settlement. Equal outside cash flows are included, so this is not a standalone investment-return curve.",'CHART 01 · WEALTH');lineChart(s.panel,['A','B','C','D'].map(k=>dailySeries(r,k,'total_investor_wealth')),"Four-strategy book wealth and final liquidation wealth");s=section(out,"Rule-triggered losses and capital tax paid differences","Left: cumulative losses from harvesting rules only. Other losses from QP and rebalancing trades appear in the annual and lot ledgers. Right: paired control tax paid minus strategy tax paid, also affected by different returns and trading paths.",'CHART 02 · LOSSES & TAX CASH FLOWS');const split=add(s.panel,'div','chart-split'),loss=add(split,'div'),tax=add(split,'div');add(loss,'h4','',"Rule-triggered harvested losses (USD)");lineChart(loss,['B','D'].map(k=>dailySeries(r,k,'cumulative_harvested_losses')),"Rule-triggered harvested losses",{zero:true});add(tax,'h4','',"Capital tax paid difference (USD; positive or negative)");lineChart(tax,[differenceSeries(r,'B','A','cumulative_capital_tax',"A tax paid − B tax paid"),differenceSeries(r,'D','C','cumulative_capital_tax',"C tax paid − D tax paid")],"Paired capital tax paid differences",{zero:true});add(s.panel,'p','axis-note',"A positive tax difference means the strategy has paid less capital tax to date. It does not establish permanent tax savings or pure tax alpha.");s=section(out,"Potential tax on positive unrealized gains","Estimated from each positive unrealized lot gain and modeled tax rate, before offsets for losses, carryforwards or cross-character netting. This is a liability proxy, not an exact tax bill; it returns to zero after liquidation.",'CHART 03 · EMBEDDED TAX');lineChart(s.panel,['A','B','C','D'].map(k=>dailySeries(r,k,'embedded_tax_liability_estimate')),"Potential tax on positive unrealized gains",{zero:true});}
 function costDetail(parent,row){parent.replaceChildren();if(!row)return;add(parent,'h4','',"Financing "+rate(row.financing_pct)+" · Borrow "+rate(row.borrow_pct));if(row.status!=='completed'){add(parent,'p','warning',"This cell did not complete. It is neither a zero result nor valid evidence of strategy underperformance. "+(row.error||''));return;}table(parent,[["A wealth",'wealth_A',money],["B wealth",'wealth_B',money],["C wealth",'wealth_C',money],["D wealth",'wealth_D',money],['D − A','delta_D_A',signed],['D − C','delta_D_C',signed]],[row]);}
 function renderSensitivity(out,r){const data=r.sensitivity||{},rows=data.rows||[];const {panel,head}=section(out,"Does D's advantage change as costs rise?","Rerun strategies at each cost pair using the same securities, prices, initial cash and outside gains. Cell counts describe tested cost settings, not future win probabilities.",'CHART 04 · COST SENSITIVITY');if(!rows.length){add(panel,'p','explain',"No cost grid was run. Enable cost sensitivity and rerun to compare financing and borrow rates.");return;}const control=add(head,'label','metric-control',"Show difference");const select=add(control,'select');select.id='sensitivity-metric';for(const[value,name]of [['delta_D_A',"D vs A: Index"],['delta_D_C',"D vs C: No harvesting"]]){const o=add(select,'option','',name);o.value=value;}select.value=metric;const fs=[...new Set(rows.map(x=>x.financing_pct))].sort((a,b)=>a-b),bs=[...new Set(rows.map(x=>x.borrow_pct))].sort((a,b)=>a-b);const wrap=add(panel,'div','table-scroll'),t=add(wrap,'table','heatmap'),h=add(add(t,'thead'),'tr');add(h,'th','',"Borrow ↓ / Financing →");fs.forEach(f=>add(h,'th','',rate(f)));const tbody=add(t,'tbody'),detail=el('div','cell-detail');if(!selectedCost)selectedCost=rows.find(x=>x.status==='completed')||rows[0];for(const b of bs){const tr=add(tbody,'tr');add(tr,'th','',rate(b));for(const f of fs){const row=rows.find(x=>x.financing_pct===f&&x.borrow_pct===b);const td=add(tr,'td');if(!row){add(td,'span','',"Not provided");continue;}const ok=row.status==='completed',value=row[metric];const button=add(td,'button','heat-cell '+(!ok?'failed':value<0?'negative':'positive')+(row===selectedCost?' selected':''),ok?signed(value):"Incomplete");button.type='button';button.setAttribute('aria-label',"Financing "+rate(f)+", borrow "+rate(b)+", "+(ok?signed(value):"Incomplete"));button.addEventListener('click',()=>{selectedCost=row;t.querySelectorAll('.selected').forEach(n=>n.classList.remove('selected'));button.classList.add('selected');costDetail(detail,row);});}}panel.appendChild(detail);costDetail(detail,selectedCost);const done=rows.filter(x=>x.status==='completed'&&finite(x[metric])),failed=rows.length-done.length;add(panel,'p','axis-note',"Completed "+done.length+" / "+rows.length+" cells; incomplete "+failed+" cells. Positive differences: "+done.filter(x=>x[metric]>0).length+" cells; negative differences: "+done.filter(x=>x[metric]<0).length+" cells.");if(failed)add(panel,'p','warning',"Some cost scenarios did not complete. Do not exclude failed cells and claim the entire range is favorable.");const brackets=[];for(const b of bs){for(let i=0;i<fs.length-1;i++){const a=rows.find(x=>x.financing_pct===fs[i]&&x.borrow_pct===b),z=rows.find(x=>x.financing_pct===fs[i+1]&&x.borrow_pct===b);if(a?.status==='completed'&&z?.status==='completed'&&a[metric]*z[metric]<0)brackets.push({borrow:rate(b),range:rate(fs[i])+' – '+rate(fs[i+1]),delta:signed(a[metric])+' → '+signed(z[metric])});}}if(brackets.length)table(panel,[["Fixed borrow rate",'borrow'],["Financing sign-change interval",'range'],["Tested differences",'delta']],brackets);else add(panel,'p','axis-note',"No sign-change interval was found between adjacent completed points. Untested rates may still contain a crossing; this does not establish that no break-even threshold exists.");add(panel,'p','axis-note',"A sign change only brackets a crossing between two tested points; it does not solve for an exact rate. Failed cells are not bridged.");select.addEventListener('change',()=>{metric=select.value;render(lastResult,false);$('sensitivity-metric').focus();});}
 function renderRisk(out,r){const {panel}=section(out,"How much additional risk accompanies the wealth result?","Calculated from pre-tax, pre-fee investment returns, excluding outside cash flows. Position/NAV and gross exposure are observed period maxima and may drift above rebalancing targets. ETFs are treated as whole positions, without look-through. These metrics are not risk-adjusted alpha or future risk limits.");const rows=comparisonRows(r).map(row=>{const risk=r.strategies?.[row.strategy]?.risk||{};return{...row,te:risk.tracking_error??row.tracking_error,vol:risk.volatility??row.volatility,dd:risk.max_drawdown??row.max_drawdown,concentration:risk.max_concentration??row.concentration,gross:risk.max_gross_exposure??row.max_gross_exposure};});table(panel,[["Strategy",'label'],["Annualized tracking error",'te',pct],["Annualized volatility",'vol',pct],["Maximum drawdown",r=>finite(r.dd)?Math.abs(r.dd):null,pct],["Largest position / NAV",'concentration',pct],["Maximum gross exposure",r=>finite(r.gross)?r.gross.toFixed(2)+'×':'—'],["Maintenance liquidations",'margin_liquidations',decimal]],rows);}
 function renderMC(out,r){const data=r.monte_carlo||{},rows=data.rows||[];if(!rows.length)return;const d=details(out,"Additional simulated paths: model-conditional distribution",true);add(d,'p','explain',"All strategies share the same shocks within each path. The path model and seed determine this distribution. Small-sample proportions are not real-world success probabilities.");const done=rows.filter(x=>x.status==='completed'),s=data.summary||{};add(d,'p','axis-note',"Completed "+done.length+" / "+rows.length+"; failed "+(rows.length-done.length)+". Median D−A difference: "+signed(s.median_delta)+"; 5th–95th percentile: "+signed(s.p05)+" to "+signed(s.p95)+".");table(d,[["Path",x=>x.path??x.path_id??x.sample_id],["Status",'status'],["D wealth",'wealth_D',money],['D − A','delta_D_A',signed],['D − C','delta_D_C',signed],["Failure reason",'error']],rows);}
 function renderDetails(out,r){const d=details(out,"Annual tax, trade and lot records");const select=add(d,'select','detail-select');select.id='ledger-strategy';Object.keys(labels).forEach(k=>{const o=add(select,'option','',labels[k]);o.value=k;});select.value='D';const body=add(d,'div');function ledger(){body.replaceChildren();const run=r.strategies?.[select.value]||{};add(body,'h4','subheading',"Annual capital tax and loss utilization");table(body,[["Year",'year'],["Payment date",'payment_date'],["ST gains",'realized_st_gain',money],["LT gains",'realized_lt_gain',money],["ST losses",'realized_st_loss',money],["LT losses",'realized_lt_loss',money],["Capital tax",'tax',money],["ST carryforward",'carry_st',money],["LT carryforward",'carry_lt',money]],run.annual||[]);add(body,'h4','subheading',"Trades (first 100; complete records in ZIP)");table(body,[["Date",'date'],["Ticker",'ticker'],["Side",'side'],["Reason",'reason'],["Shares",'shares',decimal],["Price",'price',money],["Fee",'fee',money]],(run.trades||[]).slice(0,100));add(body,'h4','subheading',"Realized lot gains and losses (first 100)");table(body,[["Date",'date'],["Ticker",'ticker'],["Side",'side'],["Lot",'lot_id'],["Shares",'shares',decimal],["Economic P&L",'economic_pnl',money],["Tax P&L",'tax_pnl',money],["Wash-sale deferral",'wash_disallowed',money],["Character",'character']],(run.realizations||[]).slice(0,100));}ledger();select.addEventListener('change',ledger);const decisions=r.strategies?.D?.optimizer_decisions||[];const q=details(out,"D: optimization decisions and estimation inputs");add(q,'p','explain',"Selects weights and trades within fixed long/short directions using then-available risk estimates and a local positive-gain tax-cost approximation. The current optimization objective is not lifetime after-tax wealth; actual modeled taxes are calculated by the ledger.");add(q,'p','axis-note',"Decision records: "+decisions.length+"; the first 12 are shown. Complete records are included in the ZIP.");add(q,'pre','',JSON.stringify(decisions.slice(0,12),null,2));const limits=details(out,"Model scope and limitations for this run");const list=add(limits,'ul');(r.limitations||[]).forEach(x=>add(list,'li','',typeof x==='string'?x:JSON.stringify(x)));const provenance=details(out,"Data snapshot and code versions");add(provenance,'pre','',JSON.stringify({run_id:r.run_id,data_kind:r.data_kind,data_label:r.data_label,data_metadata:r.data_metadata,engine_hashes:r.engine_hashes,optimization:r.request?.optimization,sensitivities:r.request?.sensitivities,monte_carlo:r.request?.monte_carlo},null,2));}
 function render(r,fresh=true){const out=$('output');out.replaceChildren();if(fresh)selectedCost=null;renderTop(out,r);renderCharts(out,r);renderSensitivity(out,r);renderRisk(out,r);renderMC(out,r);renderDetails(out,r);if(fresh){dirty=false;out.classList.remove('old-result');$('stale').hidden=true;$('export').disabled=false;$('print').disabled=false;}}
 function setBusy(value){busy=value;$('fields').disabled=value;$('run').disabled=value;$('reset').disabled=value;$('results').setAttribute('aria-busy',value?'true':'false');$('export').disabled=value||!lastResult||dirty;$('print').disabled=value||!lastResult||dirty;optionalFields();}
 $('lab-form').addEventListener('submit',async event=>{event.preventDefault();if(!defaults||busy)return;$('form-error').hidden=true;let request;try{if(!$('lab-form').reportValidity())return;request=await payload();}catch(e){$('form-error').textContent=e.message;$('form-error').hidden=false;$('status').textContent="Correct the inputs before running the study.";return;}setBusy(true);seconds=0;$('status').textContent="Building four strategies, optimization decisions and full-liquidation results…";timer=window.setInterval(()=>{$('status').textContent="Calculating · elapsed "+(++seconds)+" seconds. Waiting for complete results; this is not an estimated completion percentage.";},1000);try{const response=await fetch('/api/tax-lab/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)});let r;try{r=await response.json();}catch(_){throw Error("The server did not return valid JSON. Check the launch window.");}if(!response.ok)throw Error(r.error||"The study did not complete.");if(!r.strategies||!r.comparison||!r.run_id)throw Error("The response is missing four-strategy results. The previous study has been retained.");lastResult=r;render(r);$('status').textContent="Four-strategy study complete. Review wealth differences, then taxes, potential liabilities and risk.";if(window.matchMedia('(max-width:850px)').matches)$('results').scrollIntoView({block:'start',behavior:'smooth'});}catch(e){$('form-error').textContent=e.message==='Failed to fetch'?"Unable to connect to the preview service. Check that the launcher is still running.":e.message;$('form-error').hidden=false;$('status').textContent=lastResult?"This run did not complete. Previous results are retained; review the error and rerun.":"This run did not complete. Review the error for details.";}finally{window.clearInterval(timer);setBusy(false);}});
 $('lab-form').addEventListener('input',markDirty);$('lab-form').addEventListener('change',markDirty);
 $('data-source').addEventListener('change',()=>{if(!defaults||busy)return;const group=sourceGroup();if(group!==activeGroup){drafts[activeGroup]=draft();applyGroup(baseConfig(),drafts[group]);activeGroup=group;}sourceNote();markDirty();});
 $('reset').addEventListener('click',reset);$('export').addEventListener('click',()=>{if(lastResult&&!dirty&&!busy)window.location.href='/api/tax-lab/download/'+encodeURIComponent(lastResult.run_id);});$('print').addEventListener('click',()=>{if(lastResult&&!dirty&&!busy)window.print();});
 fetch('/api/tax-lab/defaults').then(async response=>{if(!response.ok)throw Error("Unable to load study defaults.");const d=await response.json();if(!d.demo_config||!d.observed_config)throw Error("Demo or historical settings are missing.");defaults=d;reset();setBusy(false);}).catch(e=>{$('boot-error').textContent=e.message+" Check that you are using the independent Tax-Aware Lab launcher.";$('boot-error').hidden=false;$('status').textContent="Parameters have not loaded. No calculation has started.";});
})();
